// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-06-share-button-geometry-and-absence.spec.ts, план .qa/e2e/specs/guided-prayer.md, кейс .qa/tests/guided-prayer/GP-06-share-prayer-button.md
// Тикет #6a86f7df · 6a86f7df6f29cb4c367083d2 «עיצוב מוקאפ: תפילה מודרכת — קטע בתוך סדר התפילה». Опора: мокап S-17 (Figma 608:1726).
// Размер 48×48 и радиус (getComputedStyle) не переносятся — в приложении пиксели устройства; порядок кнопок — через getLocation.
import { expect, driver } from '@wdio/globals';
import { byText, byTextMatches, byLabel, byLabelStartsWith, tapText, expectVisibleText, pageCounter, scrollToText } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

async function switchNusach(to: 'ספרדי' | 'אשכנזי') {
  await (await byLabelStartsWith('בחירת נוסח')).click();
  await tapText(to);
  const replace = await byText('החלף');
  if (await replace.isDisplayed().catch(() => false)) await replace.click();
  await expectVisibleText(`מנחה (${to})`);
}

/** Прямоугольник элемента (единицы — как у getWindowSize на этой платформе). */
async function box(el: ReturnType<typeof byText>) {
  const { x, y } = await el.getLocation();
  const { width, height } = await el.getSize();
  return { x, y, width, height };
}

/** Открыть ключ через deep link; true — экран молитвы открылся (счётчик или «האזן להקראה»), false — варианта нет. */
async function openKey(key: string) {
  await toHome();
  await openRoute(`/prayer/${key}`);
  return driver.waitUntil(async () =>
    (await (await byTextMatches('\\d+ מתוך \\d+')).isDisplayed().catch(() => false)) ||
    (await (await byText('האזן להקראה')).isDisplayed().catch(() => false)),
  { timeout: 10000 }).then(() => true, () => false);
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-06 «שיתוף התפילה»: под «קודם»/«סיים תפילה», над «האזן להקראה» (מנחה ספרד, 2 מתוך 11) #6a86f7df @prod-safe', async () => {
    // 1. מנחה (ספרדי) «2 מתוך 11».
    if (hasDeepLinks()) await openRoute('/prayer/mincha_sfarad');
    else { await openPrayer('mincha_ashkenaz', 'מנחה'); await switchNusach('ספרדי'); }
    await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();
    await goToPage(2, 11);
    expect(await pageCounter()).toBe('2 מתוך 11');

    // 2. Порядок по вертикали: «קודם» и «סיים תפילה» выше «שיתוף התפילה», «האזן להקראה» ниже.
    const share = await byLabel('שיתוף התפילה');
    if (!(await share.isDisplayed().catch(() => false))) await scrollToText('האזן להקראה');
    await expect(share).toBeDisplayed();
    const s = await box(byLabel('שיתוף התפילה'));
    const prev = await box(byText('קודם'));
    const finish = await box(byText('סיים תפילה'));
    const listen = await box(byText('האזן להקראה'));
    expect(s.y).toBeGreaterThanOrEqual(prev.y + prev.height);
    expect(s.y).toBeGreaterThanOrEqual(finish.y + finish.height);
    expect(s.y + s.height).toBeLessThanOrEqual(listen.y);

    if (!hasDeepLinks()) {
      await toHome();
      await openPrayer('mincha_ashkenaz', 'מנחה');
      await switchNusach('אשכנזי');
    }
  });

  it('GP-06 «שיתוף התפילה» нет в дополнениях (ספירת העומר, מזמור ק״ל) и в ברכה #6a86f7df @prod-safe', async function () {
    if (!hasDeepLinks()) this.skip();   // дополнения и ברכות по ключу — только через deep link (APP_SCHEME)
    // 3. sefirat_haomer / psalm_130: вариант אשכנז, иначе ספרד — кнопки нет.
    for (const key of ['sefirat_haomer_ashkenaz', 'psalm_130_ashkenaz']) {
      const opened = (await openKey(key)) || (await openKey(key.replace('_ashkenaz', '_sfarad')));
      expect(opened).toBe(true);
      await scrollToText('האזן להקראה', 6).catch(() => {});   // кнопка была бы рядом с блоком «האזן להקראה»
      await expect(byLabel('שיתוף התפילה')).not.toBeDisplayed();
    }
    // 4. Первая ברכה (נטילת ידים והמוציא) — кнопки нет.
    expect(await openKey('beracha_hamotzi_ashkenaz')).toBe(true);
    await scrollToText('האזן להקראה', 6).catch(() => {});
    await expect(byLabel('שיתוף התפילה')).not.toBeDisplayed();
  });
});
